    window.pawWiggle = function(event) { event.stopPropagation(); const paw = event.currentTarget; paw.classList.add('paw-wiggle'); paw.addEventListener('animationend', () => paw.classList.remove('paw-wiggle'), { once: true }); }
    window.handleCharacterClick = function(characterName) { const detailView = document.getElementById('character-detail-view'); isoKikiIndex = 0; document.getElementById('easter-egg-output').textContent = ''; document.getElementById('easter-egg-output').style.opacity = '0'; if (detailView.classList.contains('active') && currentCharacter === characterName) { switchView('characters'); currentCharacter = null; } else { currentCharacter = characterName; document.getElementById('detail-name').textContent = characterName; if (gameData) updateCharacterDetail(); switchView('character-detail'); } }
    function showIsoKikiEasterEgg() { const outputEl = document.getElementById('easter-egg-output'); isoKikiIndex++; if (isoKikiIndex > isoKikiText.length) { outputEl.style.opacity = '0'; isoKikiIndex = 0; setTimeout(() => { outputEl.textContent = ''; }, 200); } else { outputEl.style.opacity = '1'; outputEl.textContent = isoKikiText.substring(0, isoKikiIndex); } }
    window.toggleAuthorPopup = function() { const popupOverlay = document.getElementById('author-popup-overlay'); popupOverlay.classList.toggle('show'); }
    function setProgressBar(progressId, valueId, value) { const progressEl = document.getElementById(progressId); const valueEl = document.getElementById(valueId); const numValue = parseInt(value) || 0; if (progressEl) progressEl.style.width = numValue + '%'; if (valueEl) valueEl.textContent = numValue; }

    // ===============================================================
    // 茶茶的智能盖章师傅来啦！
    // ===============================================================
    function setStamp(id, value) {
        const el = document.getElementById(id);
        if (el) {
            // 智能安检：不管你是真的true，还是穿着"true"马甲的文字，都给你盖“是”！
            const isStamped = (value === true || String(value).toLowerCase() === 'true');
            el.textContent = isStamped ? '是' : '否';
            el.className = `stamp ${isStamped ? 'yes' : 'no'}`;
        }
    }
    // ===============================================================

    function safeGetValue(data, path, defaultValue = '未知') {
        const value = path.split('.').reduce((acc, part) => acc && acc[part], data);
        if (value === undefined || value === null) return defaultValue;
        if (Array.isArray(value) && value.length > 0) { return typeof value[0] === 'boolean' ? value[0] : String(value[0]) || defaultValue; }
        if (Array.isArray(value)) { return value; }
        return String(value) === '' ? defaultValue : value;
    }

    function setText(id, text) { const el = document.getElementById(id); if (el) el.textContent = text; }

    async function populateData() {
        try {
            if (typeof getChatMessages !== 'function' || typeof getCurrentMessageId !== 'function') return;
            const messages = await getChatMessages(getCurrentMessageId()); 
            const data = messages?.[0]?.data?.stat_data; if (!data) return;
            gameData = data; 

            setText('env-location', safeGetValue(data, '环境.地点'));
            setText('env-date', safeGetValue(data, '环境.日期'));
            setText('env-time', safeGetValue(data, '环境.时间'));
            setText('env-stage', safeGetValue(data, '环境.支配阶段'));

            characters.forEach(name => {
                const enName = characterMap[name];
                const bubbleEl = document.getElementById(`bubble-container-${enName}`);
                const statusEl = document.getElementById(`bubble-status-${enName}`);
                if (!bubbleEl || !statusEl) return;

                const presenceState = safeGetValue(gameData, `角色状态.${name}.在场状态`, "场外");
                const isActive = presenceState === '场内';

                statusEl.textContent = isActive ? '活跃中' : '休眠中';
                statusEl.style.color = isActive ? '#aeffae' : 'rgba(255,255,255,0.8)';
                if (isActive) {
                    bubbleEl.classList.add('is-active');
                } else {
                    bubbleEl.classList.remove('is-active');
                }
            });

            if (currentCharacter) updateCharacterDetail();
            updateAffinityView();

        } catch (error) { console.error('数据加载错误:', error); }
    }
    setInterval(populateData, 2000);
})();
</script>
