<script>
(function() {
    const characters = ['苏沐玥', '林可可', '陈曦', '赵静姝', '萧潇'];
    const characterMap = {'苏沐玥':'sumuyue', '林可可':'linkeke', '陈曦':'chenxi', '赵静姝':'zhaojingshu', '萧潇': 'xiaoxiao'};
    let currentCharacter = null; let gameData = null; let userName = '你';
    let isoKikiIndex = 0;
    const isoKikiText = "iso_kiki";

    document.addEventListener('DOMContentLoaded', () => {
        setTimeout(() => { 
            document.getElementById('loading').classList.add('hidden'); 
            generateCharacterBubbles();
            generateAffinityView();
            populateData(); 
        }, 1500);

        const sakuraContainer = document.getElementById('sakura-container');
        for (let i = 0; i < 80; i++) { const sakura = document.createElement('div'); sakura.className = 'sakura'; sakura.textContent = '🌸'; sakura.style.left = Math.random() * 100 + 'vw'; sakura.style.fontSize = Math.random() * 1 + 0.5 + 'rem'; sakura.style.animationDuration = Math.random() * 8 + 7 + 's'; sakura.style.animationDelay = Math.random() * 10 + 's'; sakuraContainer.appendChild(sakura); }
        document.querySelectorAll('.theme-btn').forEach(btn => btn.addEventListener('click', () => { document.body.dataset.theme = btn.dataset.theme; document.querySelectorAll('.theme-btn').forEach(b => b.classList.remove('active')); btn.classList.add('active'); }));
        document.getElementById('font-size-slider').addEventListener('input', (e) => { document.documentElement.style.fontSize = e.target.value + 'px'; });
        document.querySelectorAll('.color-btn').forEach(btn => btn.addEventListener('click', (e) => {
            const color = e.target.dataset.color;
            document.documentElement.style.setProperty('--primary-color', color);
            document.querySelectorAll('.color-btn').forEach(b => b.classList.remove('active'));
            e.target.classList.add('active');
        }));
        document.getElementById('detail-name-container').addEventListener('click', showIsoKikiEasterEgg);
    });

    window.switchView = function(viewName) {
        document.querySelectorAll('.content-view').forEach(view => view.classList.remove('active'));
        document.querySelectorAll('.nav-btn').forEach(btn => btn.classList.remove('active'));
        const viewEl = document.getElementById(viewName + '-view');
        const btnEl = document.querySelector(`[onclick="switchView('${viewName}')"]`);
        if (viewEl) viewEl.classList.add('active'); if (btnEl) btnEl.classList.add('active');
    }

    function generateCharacterBubbles() {
        const container = document.getElementById('character-bubbles'); let html = '';
        characters.forEach(name => {
            html += `<div class="character-bubble" id="bubble-container-${characterMap[name]}" onclick="handleCharacterClick('${name}')">
                        <div class="cat-ears">∧ ∧</div>
                        <div class="waving-paw left" onclick="pawWiggle(event)"><div class="paw-body"><div class="main-pad"></div><div class="toe-pad t1"></div><div class="toe-pad t2"></div><div class="toe-pad t3"></div></div></div>
                        <div class="waving-paw right" onclick="pawWiggle(event)"><div class="paw-body"><div class="main-pad"></div><div class="toe-pad t1"></div><div class="toe-pad t2"></div><div class="toe-pad t3"></div></div></div>
                        <div class="bubble-name">${name}</div>
                        <div class="bubble-status" id="bubble-status-${characterMap[name]}">休眠中</div>
                        <div class="active-marker">💬</div>
                     </div>`;
        });
        container.innerHTML = html;
    }

    function generateAffinityView() {
        const container = document.getElementById('affinity-container');
        if (!container) return;
        let html = '';
        characters.forEach(name => {
            const enName = characterMap[name];
            html += `
            <div class="affinity-character-card">
                <div class="affinity-char-name">${name}</div>
                <div class="confront-bar-wrapper">
                    <div class="confront-bar-container">
                        <div class="confront-bar-segment confront-bar-user" id="bar-user-${enName}"></div>
                        <div class="confront-bar-segment confront-bar-ming" id="bar-ming-${enName}"></div>
                    </div>
                    <div class="confront-labels">
                        <div class="user-label" id="label-user-${enName}">你: 0</div>
                        <div class="ming-label" id="label-ming-${enName}">阿明: 0</div>
                    </div>
                </div>
                <div class="affinity-stamps-grid">
                    <div class="stamp-item">
                        <div class="stamp-label">烙印状态</div>
                        <div class="stamp no" id="stamp-branded-${enName}">否</div>
                    </div>
                    <div class="stamp-item">
                        <div class="stamp-label">见证状态</div>
                        <div class="stamp no" id="stamp-witnessed-${enName}">否</div>
                    </div>
                </div>
            </div>`;
        });
        container.innerHTML = html;
    }


    function updateCharacterDetail() {
        if (!currentCharacter || !gameData) return;
        const presenceState = safeGetValue(gameData, `角色状态.${currentCharacter}.在场状态`, "场外");
        const isActive = presenceState === '场内';
        const defaultValue = isActive ? '未知' : '休眠中';
        setText('detail-mood', safeGetValue(gameData, `角色状态.${currentCharacter}.心情`, defaultValue));
        setText('detail-pose', safeGetValue(gameData, `角色状态.${currentCharacter}.姿势`, defaultValue));
        setText('detail-idea', safeGetValue(gameData, `角色状态.${currentCharacter}.想法`, defaultValue));
        setText('detail-top', safeGetValue(gameData, `角色状态.${currentCharacter}.上身`, defaultValue));
        setText('detail-bottom', safeGetValue(gameData, `角色状态.${currentCharacter}.下身`, defaultValue));
        setText('detail-bra', safeGetValue(gameData, `角色状态.${currentCharacter}.内衣`, defaultValue));
        setText('detail-panties', safeGetValue(gameData, `角色状态.${currentCharacter}.内裤`, defaultValue));
        setText('detail-vagina', safeGetValue(gameData, `角色状态.${currentCharacter}.小穴`, defaultValue));
        setText('detail-breasts', safeGetValue(gameData, `角色状态.${currentCharacter}.胸部`, defaultValue));
        setText('detail-anus', safeGetValue(gameData, `角色状态.${currentCharacter}.肛门`, defaultValue));
    }

    function updateAffinityView() {
        if (!gameData) return;
        characters.forEach(name => {
            const enName = characterMap[name];
            const affUser = parseInt(safeGetValue(gameData, `核心亲密度.${name}.对你的亲密度`, 0));
            const affMing = parseInt(safeGetValue(gameData, `核心亲密度.${name}.对阿明亲密度`, 0));

            const totalAff = affUser + affMing;
            const userPercent = (totalAff === 0) ? 50 : (affUser / totalAff) * 100;

            const userBar = document.getElementById(`bar-user-${enName}`);
            const mingBar = document.getElementById(`bar-ming-${enName}`);
            if(userBar) userBar.style.width = `${userPercent}%`;
            if(mingBar) mingBar.style.width = `${100 - userPercent}%`;

            setText(`label-user-${enName}`, `你: ${affUser}`);
            setText(`label-ming-${enName}`, `阿明: ${affMing}`);

            setStamp(`stamp-branded-${enName}`, safeGetValue(gameData, `核心亲密度.${name}.是否被烙印`, false));
            setStamp(`stamp-witnessed-${enName}`, safeGetValue(gameData, `核心亲密度.${name}.是否被强制见证`, false));
        });
    }

    window.pawWiggle = function(event) { event.stopPropagation(); const paw = event.currentTarget; paw.classList.add('paw-wiggle'); paw.addEventListener('animationend', () => paw.classList.remove('paw-wiggle'), { once: true }); }
    window.handleCharacterClick = function(characterName) { const detailView = document.getElementById('character-detail-view'); isoKikiIndex = 0; document.getElementById('easter-egg-output').textContent = ''; document.getElementById('easter-egg-output').style.opacity = '0'; if (detailView.classList.contains('active') && currentCharacter === characterName) { switchView('characters'); currentCharacter = null; } else { currentCharacter = characterName; document.getElementById('detail-name').textContent = characterName; if (gameData) updateCharacterDetail(); switchView('character-detail'); } }
    function showIsoKikiEasterEgg() { const outputEl = document.getElementById('easter-egg-output'); isoKikiIndex++; if (isoKikiIndex > isoKikiText.length) { outputEl.style.opacity = '0'; isoKikiIndex = 0; setTimeout(() => { outputEl.textContent = ''; }, 200); } else { outputEl.style.opacity = '1'; outputEl.textContent = isoKikiText.substring(0, isoKikiIndex); } }
    window.toggleAuthorPopup = function() { const popupOverlay = document.getElementById('author-popup-overlay'); popupOverlay.classList.toggle('show'); }
    function setProgressBar(progressId, valueId, value) { const progressEl = document.getElementById(progressId); const valueEl = document.getElementById(valueId); const numValue = parseInt(value) || 0; if (progressEl) progressEl.style.width = numValue + '%'; if (valueEl) valueEl.textContent = numValue; }

    // ===============================================================
    // 茶茶的智能盖章师傅来啦！
    // ===============================================================
    function setStamp(id, value) {
        const el = document.getElementById(id);
        if (el) {
            // 智能安检：不管你是真的true，还是穿着"true"马甲的文字，都给你盖“是”！
            const isStamped = (value === true || String(value).toLowerCase() === 'true');
            el.textContent = isStamped ? '是' : '否';
            el.className = `stamp ${isStamped ? 'yes' : 'no'}`;
        }
    }
    // ===============================================================

    function safeGetValue(data, path, defaultValue = '未知') {
        const value = path.split('.').reduce((acc, part) => acc && acc[part], data);
        if (value === undefined || value === null) return defaultValue;
        if (Array.isArray(value) && value.length > 0) { return typeof value[0] === 'boolean' ? value[0] : String(value[0]) || defaultValue; }
        if (Array.isArray(value)) { return value; }
        return String(value) === '' ? defaultValue : value;
    }

    function setText(id, text) { const el = document.getElementById(id); if (el) el.textContent = text; }

    async function populateData() {
        try {
            if (typeof getChatMessages !== 'function' || typeof getCurrentMessageId !== 'function') return;
            const messages = await getChatMessages(getCurrentMessageId()); 
            const data = messages?.[0]?.data?.stat_data; if (!data) return;
            gameData = data; 

            setText('env-location', safeGetValue(data, '环境.地点'));
            setText('env-date', safeGetValue(data, '环境.日期'));
            setText('env-time', safeGetValue(data, '环境.时间'));
            setText('env-stage', safeGetValue(data, '环境.支配阶段'));

            characters.forEach(name => {
                const enName = characterMap[name];
                const bubbleEl = document.getElementById(`bubble-container-${enName}`);
                const statusEl = document.getElementById(`bubble-status-${enName}`);
                if (!bubbleEl || !statusEl) return;

                const presenceState = safeGetValue(gameData, `角色状态.${name}.在场状态`, "场外");
                const isActive = presenceState === '场内';

                statusEl.textContent = isActive ? '活跃中' : '休眠中';
                statusEl.style.color = isActive ? '#aeffae' : 'rgba(255,255,255,0.8)';
                if (isActive) {
                    bubbleEl.classList.add('is-active');
                } else {
                    bubbleEl.classList.remove('is-active');
                }
            });

            if (currentCharacter) updateCharacterDetail();
            updateAffinityView();

        } catch (error) { console.error('数据加载错误:', error); }
    }
    setInterval(populateData, 2000);
})();
</script>
</body>
</html>
