---
<%_
  // --- 步骤1：安全地获取所有亲密度变量，并用 Number() 强制转换为数字！ ---
  const su_ming = Number(getvar('stat_data.核心亲密度.苏沐玥.对阿明亲密度[0]')) ?? 40;
  const su_user = Number(getvar('stat_data.核心亲密度.苏沐玥.对你的亲密度[0]')) ?? 25;
  const lk_ming = Number(getvar('stat_data.核心亲密度.林可可.对阿明亲密度[0]')) ?? 50;
  const lk_user = Number(getvar('stat_data.核心亲密度.林可可.对你的亲密度[0]')) ?? 20;
  const cx_ming = Number(getvar('stat_data.核心亲密度.陈曦.对阿明亲密度[0]')) ?? 65;
  const cx_user = Number(getvar('stat_data.核心亲密度.陈曦.对你的亲密度[0]')) ?? 20;
  const zj_ming = Number(getvar('stat_data.核心亲密度.赵静姝.对阿明亲密度[0]')) ?? 90;
  const zj_user = Number(getvar('stat_data.核心亲密度.赵静姝.对你的亲密度[0]')) ?? 30;
  const xx_ming = Number(getvar('stat_data.核心亲密度.萧潇.对阿明亲密度[0]')) ?? 10;
  const xx_user = Number(getvar('stat_data.核心亲密度.萧潇.对你的亲密度[0]')) ?? 40;
  const allWitnessed = (getvar('stat_data.核心亲密度.苏沐玥.是否被强制见证[0]') ?? false) && (getvar('stat_data.核心亲密度.林可可.是否被强制见证[0]') ?? false) && (getvar('stat_data.核心亲密度.陈曦.是否被强制见证[0]') ?? false) && (getvar('stat_data.核心亲密度.赵静姝.是否被强制见证[0]') ?? false) && (getvar('stat_data.核心亲密度.萧潇.是否被强制见证[0]') ?? false);

  // --- 步骤2：进行精准的数学计算 ---
  const totalMing = su_ming + lk_ming + cx_ming + zj_ming + xx_ming;
  const totalUser = su_user + lk_user + cx_user + zj_user + xx_user;
  const difference = totalMing - totalUser;

  // --- 步骤3：计算出【新的世界阶段】 ---
  let newWorldStage = '';
  if (allWitnessed && difference < -50) {
    newWorldStage = '虚拟现实后宫';
  } else if (difference < -50) {
    newWorldStage = '你的世界';
  } else if (difference >= -50 && difference <= 50) {
    newWorldStage = '天平的动摇';
  } else { // difference > 50
    newWorldStage = '阿明的世界';
  }

  // --- 步骤4：获取【当前的世界阶段】 ---
  const currentWorldStage = getvar('stat_data.环境.支配阶段[0]') ?? '未知';
_%>
